import React, { useState } from 'react';
import { useScroll, useMotionValueEvent } from 'framer-motion';
import Hero from './components/Hero';
import TargetGroup from './components/TargetGroup';
import Services from './components/Services';
import ProcessSection from './components/ProcessSection';
import PerformanceSection from './components/PerformanceSection';
import CaseStudy from './components/CaseStudy';
import FAQ from './components/FAQ';
import ContactForm from './components/ContactForm';
import Footer from './components/Footer';

const App: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const { scrollY } = useScroll();

  useMotionValueEvent(scrollY, "change", (latest) => {
    setIsScrolled(latest > 50);
  });

  const handleScroll = (e: React.MouseEvent<HTMLAnchorElement | HTMLButtonElement>, id: string) => {
    e.preventDefault();
    const element = document.getElementById(id);
    if (element) {
      const headerOffset = 100; // Height of sticky header + some buffer
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.scrollY - headerOffset;

      window.scrollTo({
        top: offsetPosition,
        behavior: "smooth"
      });
    }
  };

  return (
    <div className="min-h-screen bg-brand-light text-brand-navy selection:bg-brand-primary selection:text-white flex flex-col">
      {/* Sticky Navigation */}
      <nav 
        className={`fixed top-0 left-0 w-full z-50 transition-all duration-300 border-b ${
          isScrolled 
            ? 'bg-white/90 backdrop-blur-md border-brand-navy/10 py-3 shadow-sm' 
            : 'bg-transparent border-transparent py-5'
        }`}
      >
        <div className="container mx-auto px-6 flex items-center justify-between">
          <div className="text-xl font-extrabold tracking-tight text-brand-navy">
            OKR<span className="text-brand-primary">.digital</span>
          </div>

          <div className="flex items-center gap-8">
            <div className="hidden md:flex gap-6 text-sm font-medium text-brand-gray">
              <a href="#services" onClick={(e) => handleScroll(e, 'services')} className="hover:text-brand-primary transition-colors">Leistungen</a>
              <a href="#process" onClick={(e) => handleScroll(e, 'process')} className="hover:text-brand-primary transition-colors">Prozess</a>
              <a href="#performance" onClick={(e) => handleScroll(e, 'performance')} className="hover:text-brand-primary transition-colors">Modell</a>
              <a href="#faq" onClick={(e) => handleScroll(e, 'faq')} className="hover:text-brand-primary transition-colors">FAQ</a>
            </div>
            <button 
              onClick={(e) => handleScroll(e, 'contact')}
              className={`px-5 py-2.5 text-sm font-semibold rounded-lg transition-all inline-block ${
                isScrolled
                  ? 'bg-brand-primary text-white hover:bg-blue-700 shadow-md'
                  : 'bg-brand-navy text-white hover:bg-brand-primary shadow-lg'
              }`}
            >
              Lass uns sprechen
            </button>
          </div>
        </div>
      </nav>

      <main className="flex-grow">
        <Hero />
        <div id="target-group"><TargetGroup /></div>
        <div id="services"><Services /></div>
        <div id="process"><ProcessSection /></div>
        <div id="performance"><PerformanceSection /></div>
        <div id="proof"><CaseStudy /></div>
        <div id="faq"><FAQ /></div>
        <div id="contact"><ContactForm /></div>
      </main>

      <Footer />
    </div>
  );
};

